gWa(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0648\u0627\u0636\u062d\u0629 \u0648\u0633\u0647\u0644\u0629 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u062a\u0637\u0628\u064a\u0642 \u0647\u064a\u0626\u0629 \u0627\u0644\u062a\u0642\u0627\u0639\u062f \u0627\u0644\u0641\u0644\u0633\u0637\u064a\u0646\u064a\u0629. \u064a\u062a\u064a\u062d \u0644\u0644\u0645\u062a\u0642\u0627\u0639\u062f\u064a\u0646 \u0639\u0631\u0636 \u062a\u0641\u0627\u0635\u064a\u0644 \u0627\u0644\u0645\u0639\u0627\u0634 \u0627\u0644\u0634\u0647\u0631\u064a\u060c \u0637\u0644\u0628 \u0627\u0644\u0648\u062b\u0627\u0626\u0642 \u0627\u0644\u0631\u0633\u0645\u064a\u0629\u060c \u062a\u062a\u0628\u0639 \u0633\u0646\u0648\u0627\u062a \u0627\u0644\u062e\u062f\u0645\u0629\u060c \u0648\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u062a\u062d\u062f\u064a\u062b\u0627\u062a \u0645\u0646 \u0627\u0644\u0647\u064a\u0626\u0629."},
gSJ(){return"\u062a\u062c\u0631\u0628\u0629 \u062d\u062c\u0632 \u0627\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a"},
gQA(){return"\u062a\u0635\u0645\u064a\u0645 \u0646\u0638\u064a\u0641"},
gSx(){return"\u0644\u0648\u062d\u0629 \u0623\u0644\u0648\u0627\u0646 \u0623\u0646\u064a\u0642\u0629"},
gUd(){return"\u062a\u0637\u0628\u064a\u0642 Happy Season"},
gUf(){return"\u062a\u0628\u062f\u0623 \u0647\u0646\u0627 \u0627\u0644\u0623\u0639\u0631\u0627\u0633 \n \u0648\u062d\u062c\u0648\u0632\u0627\u062a \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0627\u062a \u0627\u0644\u0639\u0635\u0631\u064a\u0629 \ud83d\udc8d"},
gUe(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0623\u0646\u064a\u0642 \u0648\u0633\u0647\u0644 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0644\u062a\u0637\u0628\u064a\u0642 \u062d\u062c\u0632 \u0642\u0627\u0639\u0627\u062a \u0627\u0644\u0623\u0639\u0631\u0627\u0633 \u0648\u0627\u0644\u0641\u0639\u0627\u0644\u064a\u0627\u062a. \u064a\u0633\u0627\u0639\u062f Happy Season \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0642\u0627\u0639\u0627\u062a\u060c \u0645\u0642\u0627\u0631\u0646\u062a\u0647\u0627\u060c \u0648\u062d\u062c\u0632\u0647\u0627 \u0628\u0633\u0647\u0648\u0644\u0629."},
gRh(){return"\u0637\u0627\u0628\u0639 \u062b\u0642\u0627\u0641\u064a"},
