gQx(){return"\u0648\u0627\u062c\u0647\u0629 \u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u0623\u0637\u0641\u0627\u0644"},
gVE(){return"\u0645\u0648\u0642\u0639 \u062c\u0645\u0639\u064a\u0629 \u0646\u0648\u0649"},
gVG(){return"\u0642\u0644\u0648\u0628 \u0635\u063a\u064a\u0631\u0629\n\u0648\u062c\u0630\u0648\u0631 \u0639\u0645\u064a\u0642\u0629"},
gVF(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0645\u0648\u0642\u0639 \u062f\u0627\u0641\u0626 \u0648\u062c\u0630\u0627\u0628 \u0644\u0645\u0646\u0638\u0645\u0629 \u063a\u064a\u0631 \u0631\u0628\u062d\u064a\u0629 \u0645\u0643\u0631\u0633\u0629 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u0631\u0627\u062b \u0627\u0644\u062b\u0642\u0627\u0641\u064a \u0648\u062f\u0639\u0645 \u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0623\u0637\u0641\u0627\u0644."},
