gUo(){return"\u0623\u0642\u0633\u0627\u0645 \u0631\u0626\u064a\u0633\u064a\u0629"},
gR9(){return"\u062a\u0635\u0645\u064a\u0645 \u0634\u0631\u0643\u0627\u062a"},
gGY(){return"GLOBAL BUILDERS"},
gH_(){return"\u0627\u0644\u0628\u0646\u0627\u0621 \u062d\u0648\u0644 \u0627\u0644\u0639\u0627\u0644\u0645"},
gGZ(){return"\u062a\u0635\u0645\u064a\u0645 \u0635\u0641\u062d\u0629 \u0647\u0628\u0648\u0637 \u062d\u062f\u064a\u062b\u0629 \u0648\u0627\u062d\u062a\u0631\u0627\u0641\u064a\u0629 \u0644\u0634\u0631\u0643\u0629 \u0625\u0646\u0634\u0627\u0621\u0627\u062a \u0639\u0627\u0644\u0645\u064a\u0629. \u064a\u062a\u0645\u064a\u0632 \u0628\u062e\u0637\u0648\u0637 \u0642\u0648\u064a\u0629\u060c \u062a\u0633\u0644\u0633\u0644 \u0628\u0635\u0631\u064a \u0648\u0627\u0636\u062d\u060c \u0639\u0646\u0627\u0635\u0631 \u062a\u0639\u0632\u0632 \u0627\u0644\u062b\u0642\u0629\u060c \u0648\u0623\u0642\u0633\u0627\u0645 \u062a\u0639\u0631\u0636 \u0627\u0644\u062e\u062f\u0645\u0627\u062a."},
gRl(){return"\u062a\u0635\u0645\u064a\u0645 \u0644\u0648\u062d\u0629 \u062a\u062d\u0643\u0645"},
gQF(){return"\u0644\u0648\u062d\u0629 \u062a\u062d\u0643\u0645 COMPANY"},
gQH(){return"\u062d\u062f\u064a\u062b\u0629 \u0648\u0646\u0638\u064a\u0641\u0629\n\u0644\u0648\u062d\u0629 \u0625\u062f\u0627\u0631\u0629 \u062f\u0627\u062e\u0644\u064a\u0629"},
gQG(){return"\u062a\u0635\u0645\u064a\u0645 \u0648\u0627\u062c\u0647\u0629 \u0644\u0648\u062d\u0629 \u062a\u062d\u0643\u0645 \u0628\u062f\u064a\u0647\u064a\u0629 \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u062a\u0648\u0633\u0639 \u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0634\u0631\u0643\u0627\u062a \u062f\u0627\u062e\u0644\u064a\u064b\u0627. \u062a\u062a\u0636\u0645\u0646 \u0628\u0637\u0627\u0642\u0627\u062a \u062a\u062d\u0644\u064a\u0644\u0627\u062a\u060c \u0634\u0631\u064a\u0637 \u062a\u0646\u0642\u0644 \u062c\u0627\u0646\u0628\u064a\u060c \u0648\u062d\u062f\u0627\u062a \u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646\u060c \u0648\u0645\u062e\u0637\u0637\u0627\u062a \u0644\u062d\u0638\u064a\u0629."},
