gXT(){return" \ud83d\udc8c \u062a\u0644\u0647\u0645\u0646\u064a \u062f\u0627\u0626\u0645\u064b\u0627 \u0644\u0644\u0646\u0645\u0648 \u0648\u0627\u0644\u0625\u0628\u062f\u0627\u0639 \ud83d\ude80."},
gXB(){return"\u0646\u0627\u062c\u064a \u0645\u062d\u062a\u0631\u0641 \u062d\u0642\u064a\u0642\u064a \u0641\u064a\u0645\u0627 \u064a\u0642\u0648\u0645 \u0628\u0647\u060c \u0648\u0644\u0627 \u064a\u062a\u0648\u0642\u0641 \u0639\u0646 \u0625\u062f\u0647\u0627\u0634\u064a \u0628\u0623\u0639\u0645\u0627\u0644\u0647 \u0627\u0644\u062c\u0645\u064a\u0644\u0629 \u0648\u0627\u0644\u0645\u062f\u0631\u0648\u0633\u0629. \u0623\u062a\u0637\u0644\u0639 \u0628\u0634\u062f\u0629 \u0644\u0644\u0639\u0645\u0644 \u0645\u0639\u0647 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0641\u064a \u0645\u0634\u0627\u0631\u064a\u0639 \u0645\u0633\u062a\u0642\u0628\u0644\u064a\u0629."},
gXD(){return"\u0645\u0637\u0648\u0631 Flutter"},
gXC(){return"\u0623\u062d\u0645\u062f \u062c\u0645\u0627\u0644"},
gXH(){return"\u0627\u0644\u0639\u0645\u0644 \u0645\u0639 \u0646\u0627\u062c\u064a \u0643\u0627\u0646 \u062a\u062c\u0631\u0628\u0629 \u0631\u0627\u0626\u0639\u0629 \u0628\u062d\u0642. \u0627\u0647\u062a\u0645\u0627\u0645\u0647 \u0628\u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u0648\u0646\u0647\u062c\u0647 \u0627\u0644\u0625\u0628\u062f\u0627\u0639\u064a \u062c\u0639\u0644\u0627 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0633\u0644\u0633\u0629 \u0648\u0645\u0644\u0647\u0645\u0629. \u0623\u0648\u0635\u064a \u0628\u0647 \u0628\u0634\u062f\u0629!"},
gXJ(){return"\u0645\u0646\u0634\u0637 \u0631\u0626\u064a\u0633\u064a - \u062c\u0645\u0639\u064a\u0629 \u0646\u0648\u0649 \u0644\u0644\u062b\u0642\u0627\u0641\u0629"},
gXI(){return"\u062f\u064a\u0646\u0627 \u0628\u0646 \u0633\u0639\u064a\u062f"},
gXK(){return"\u0646\u0627\u062c\u064a \u064a\u062a\u062c\u0627\u0648\u0632 \u0627\u0644\u062a\u0648\u0642\u0639\u0627\u062a \u062f\u0627\u0626\u0645\u064b\u0627. \u0623\u0639\u0645\u0627\u0644\u0647 \u062a\u062a\u062d\u062f\u062b \u0639\u0646 \u0646\u0641\u0633\u0647\u0627 \u2014 \u0623\u0646\u064a\u0642\u0629\u060c \u0647\u0627\u062f\u0641\u0629\u060c \u0648\u062f\u0627\u0626\u0645\u064b\u0627 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0627\u0644\u0645\u062d\u062f\u062f. \u0644\u0627 \u0623\u0637\u064a\u0642 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631 \u0644\u0644\u062a\u0639\u0627\u0648\u0646 \u0645\u0639\u0647 \u0645\u062c\u062f\u062f\u064b\u0627."},
gXM(){return"\u0645\u0624\u0633\u0633\u0629 \u0634\u0631\u0643\u0629 \u0646\u0627\u0634\u0626\u0629"},
gXL(){return"\u0644\u064a\u0644\u0649 \u0627\u0644\u0645\u0646\u0635\u0648\u0631"},
gXN(){return"\u0639\u0645\u0644\u062a \u0645\u0639 \u0627\u0644\u0639\u062f\u064a\u062f \u0645\u0646 \u0627\u0644\u0645\u062d\u062a\u0631\u0641\u064a\u0646\u060c \u0644\u0643\u0646 \u0646\u0627\u062c\u064a \u064a\u062a\u0645\u064a\u0632 \u0628\u062a\u0641\u0627\u0646\u064a\u0647 \u0648\u0642\u062f\u0631\u062a\u0647 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0648\u062d\u0633\u0647 \u0627\u0644\u062a\u0635\u0645\u064a\u0645\u064a. \u0625\u0646\u0647 \u064a\u0641\u0647\u0645 \u062a\u0645\u0627\u0645\u064b\u0627 \u0645\u0627 \u064a\u062d\u062a\u0627\u062c\u0647 \u0627\u0644\u0645\u0634\u0631\u0648\u0639."},
gXP(){return"\u0645\u0646\u0634\u0637 \u0631\u0626\u064a\u0633\u064a - \u0623\u062e\u0635\u0627\u0626\u064a \u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a"},
