gV5(){return"\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062e\u0628\u0631\u0629 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u0648\u062a\u0634\u063a\u064a\u0644\u0647\u0627"},
gV4(){return'\u0646\u0638\u0627\u0645 \u0630\u0643\u0627\u0621 \u0627\u0635\u0637\u0646\u0627\u0639\u064a \u0645\u0635\u0645\u0645 \u0644\u0627\u0644\u062a\u0642\u0627\u0637 \u0648\u0647\u064a\u0643\u0644\u0629 \u0648\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0636\u0645\u0646\u064a\u0629 \u0644\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a. \u0645\u0646 \u062e\u0644\u0627\u0644 \u062a\u062d\u0644\u064a\u0644 \u0645\u0633\u062a\u0646\u062f\u0627\u062a \u0627\u0644\u0639\u0645\u0644\u060c \u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u062a\u0648\u0627\u0635\u0644\u060c \u0633\u062c\u0644\u0627\u062a \u0627\u0644\u0642\u0631\u0627\u0631\u0627\u062a\u060c \u0648\u062a\u0627\u0631\u064a\u062e \u0633\u064a\u0631 \u0627\u0644\u0639\u0645\u0644\u060c \u064a\u0628\u0646\u064a \u0627\u0644\u0646\u0638\u0627\u0645 \u0631\u0633\u0645\u0627\u064b \u0628\u064a\u0627\u0646\u064a\u0627\u064b \u062f\u064a\u0646\u0627\u0645\u064a\u0643\u064a\u0627\u064b \u0644\u0644\u0645\u0639\u0631\u0641\u0629 \u064a\u0628\u0642\u0649 \u0628\u0639\u062f \u0631\u062d\u064a\u0644 \u0627\u0644\u0645\u0648\u0638\u0641\u064a\u0646. \u064a\u062a\u064a\u062d \u0644\u0644\u0645\u0648\u0638\u0641\u064a\u0646 \u0627\u0644\u062c\u062f\u062f \u0623\u0648 \u0627\u0644\u0641\u0631\u0642 \u0627\u0644\u0645\u062a\u0628\u0642\u064a\u0629 \u0627\u0644\u0627\u0633\u062a\u0641\u0633\u0627\u0631 "\u0643\u064a\u0641 \u0643\u0627\u0646 \u0633\u064a\u062a\u0639\u0627\u0645\u0644 X \u0645\u0639 \u0647\u0630\u0627\u061f" \u0648\u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u062a\u0648\u062c\u064a\u0647\u0627\u062a \u0645\u0628\u0646\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062e\u0628\u0631\u0629 \u0627\u0644\u0645\u0644\u062a\u0642\u0637\u0629\u2014\u0645\u0645\u0627 \u064a\u0642\u0644\u0644 \u0645\u0646 \u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0628\u0633\u0628\u0628 \u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0644\u0627\u062a\u060c \u0627\u0644\u062a\u0633\u0631\u064a\u062d\u060c \u0623\u0648 \u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a \u0627\u0644\u0623\u0632\u0645\u0627\u062a.'},
